#include "stdafx.h"#include "Calculon.h"#include <math.h>using namespace ns_HcdTranslator;//////////////////////////////////////////////////////////////////////////void KCalculon::push_back( SCalcVar &var ){  ASSD( kStack < _countof(Stack) );  ZeroMemory( &Stack[kStack], sizeof(Stack[kStack]) );  Stack[kStack] = var;  Stack[kStack].m_bAddrVar = false;  kStack++;}void KCalculon::push_back( SCalcVar *var ){  ASSD( kStack < _countof(Stack) );  ZeroMemory( &Stack[kStack], sizeof(Stack[kStack]) );  Stack[kStack] = *var;  Stack[kStack].m_bAddrVar = true;  kStack++;}SCalcRes KCalculon::pop_back(){  ASSD( kStack >= 1 );  SCalcRes C = Stack[--kStack];  return C;}void KCalculon::Operation( eToken_value cmd ){  switch( cmd )  {  default:    ASSD(0);    break;  case etNOT:    {      SCalcRes vr = pop_back();      SCalcRes res;      res = !vr;      push_back( res );    }    break;  case etOR:    {      SCalcRes vr = pop_back();      SCalcRes vl = pop_back();      SCalcRes res;      res = vl || vr;      push_back( res );    }    break;  case etAND:    {      SCalcRes vr = pop_back();      SCalcRes vl = pop_back();      SCalcRes res;      res = vl && vr;      push_back( res );    }    break;  case etASSIGN:    {      SCalcRes vr = pop_back();      SCalcRes vl = pop_back();      vl.Assign(vr);    }    break;  case etMINUS:  case etPLUS:  case etDIV:  case etMUL:    {      SCalcRes vr = pop_back();      SCalcRes vl = pop_back();      SCalcRes res;      res = SCalcRes::Action( vl, vr, cmd );      push_back( res );    }    break;  case etGT:  case etLT:  case etEQ:  case etNE:  case etGE:  case etLE:    {      SCalcRes vr = pop_back();      SCalcRes vl = pop_back();      bool r = vl.Compare( vr, cmd );      SCalcRes res;      res = r;      push_back( res );    }    break;  }}void KCalculon::Function( eFunctions nF ){  switch( nF )  {  default:    ASS( 0 );    break;  case efSIN:    {      SCalcRes v = pop_back();      SCalcRes res;      switch( v.GetVarType() )      {      default:        ASSD(0);        break;      case ehtAnalog32:        res.fltValue = sin( *(tAnalog32*)v.GetMem() );        res.SetVarType( ehtAnalog32 );        res.SetSize( sizeof(res.fltValue) );        break;      }      push_back( res );    }    break;  case efATAN:    {      SCalcRes v = pop_back();      SCalcRes res;      switch( v.GetVarType() )      {      default:        ASSD(0);        break;      case ehtAnalog32:        res.fltValue = atan( *(tAnalog32*)v.GetMem() );        res.SetVarType( ehtAnalog32 );        res.SetSize( sizeof(res.fltValue) );        break;      }      push_back( res );    }    break;  case efSQRT:    {      SCalcRes v = pop_back();      SCalcRes res;      switch( v.GetVarType() )      {      default:        ASSD(0);        break;      case ehtAnalog32:        res.fltValue = sqrt( *(tAnalog32*)v.GetMem() );        res.SetVarType( ehtAnalog32 );        res.SetSize( sizeof(res.fltValue) );        break;      }      push_back( res );    }    break;  case efPOW:    {      SCalcRes R = pop_back();      SCalcRes L = pop_back();      tAnalog32 l = 0;      tAnalog32 r = 0;      switch( R.GetVarType() )      {      case ehtAnalog32:        r = *(tAnalog32*)R.GetMem();        break;      case ehtDigital32:        r = *(tDigital32*)R.GetMem();        break;      }      switch( L.GetVarType() )      {      case ehtAnalog32:        l = *(tAnalog32*)L.GetMem();        break;      case ehtDigital32:        l = *(tDigital32*)L.GetMem();        break;      }      SCalcRes res;      res.fltValue = pow( l, r );      res.SetVarType( ehtAnalog32 );      res.SetSize( sizeof(res.fltValue) );      push_back( res );    }    break;  }}//////////////////////////////////////////////////////////////////////////KCalculon::KCalculon(){}tAnalog32 KCalculon::Calc(){  SCalcVar *Vars = m_pVars;  SOPElement* OP = m_pOps;  int nOP = 0;  while( nOP < m_nOps )  {    SOPElement CurrOP = (SOPElement)OP[nOP++];    switch( CurrOP.OP )    {    default:      ASSD( 0 );      break;    case OP_Operation:      Operation( OP[nOP++] );      break;    case OP_Function:      {        eFunctions nF = (eFunctions)(int)OP[nOP++];        Function( nF );      }      break;    case OP_AddrVar:      {        int N = OP[nOP++];        ASSD( N < m_nVars );        SCalcVar Var = Vars[N];        push_back( &Var );      }      break;    case OP_LoadVar:      {        int N = OP[nOP++];        ASSD( N < m_nVars );        SCalcVar Var = Vars[N];        push_back( Var );      }      break;    case OP_IF:      {        int OnFalse = OP[nOP++];// Переход по false        if( !OnFalse || OnFalse >= m_nOps )          OnFalse = m_nOps;        int OnEndif = OP[nOP++];// Переход на endif        if( !OnEndif || OnEndif >= m_nOps )          OnEndif = m_nOps;        SCalcRes V1 = pop_back();        int Next = -1;        if( !V1 )          Next = OnFalse;        if ( Next > 0 )          nOP = Next;      }      break;    case OP_ELSE:      {        int OnEndif = OP[nOP++];        ASSD(OnEndif>0 && OnEndif <= m_nOps);        nOP = OP[OnEndif];      }      break;    }  }  tAnalog32 ret = 0;  while( kStack )  {    SCalcRes V = pop_back();    ret = V;  }  return ret;}